static inline size_t StringToSizeType(const char *string,const double interval) /* <=== StringToSizeType */ 
{
  double
    value;

  value=SiPrefixToDoubleInterval(string,interval);
  if (value >= (double) MagickULLConstant(~0))
    return(~0UL);
  return((size_t) value);
}

